#!/usr/bin/env bash
set -euo pipefail
S="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")"&&pwd)";R="$(cd -- "$S/../.."&&pwd)";O="$S/milestone-7-execution-decomposition.tsv";V="$S/milestone-7-row-25-owner-validation.tsv";P="$R/plans/standards-library-effectiveness-restructure-plan.md"
mapfile -t ids < <(awk -F '\t' '$1==25{n=split($3,a,",");for(i=1;i<=n;i++)print a[i]}' "$O"|sort);expected=(STD-{0852..0858});[[ "${ids[*]}" == "${expected[*]}" ]]
[[ "$(awk -F '\t' '$1==25{print $2}' "$O"|paste -sd ' ' -)" == 1 ]];[[ "$(awk -F '\t' '$1==25&&NF!=9{n++}END{print n+0}' "$O")" -eq 0 ]]
mapfile -t validated < <(awk -F '\t' 'NR>1{print $1}' "$V");[[ "${validated[*]}" == "${expected[*]}" ]];[[ "$(awk -F '\t' 'NR>1&&($2!="workflows/implementation.md"||$3!="index"||NF!=4){n++}END{print n+0}' "$V")" -eq 0 ]]
for t in '## Owner Contract' 'identifier lineage' '## Exact Dispositions' '`STD-0852` through `STD-0858`' '## Ordered Children' '`25.1a`' '`25.1b`' '## Child 25.1 Plan Identity Replan' 'Security owns path' 'Cross-Platform applies conditionally' '## Child 25.1 Lifecycle Admission Replan' '`start` accepts only `Planned`' '`continue` accepts only `Active`' '`verify` accepts `Implemented` or `Verifying`' '## Child 25.1 Concurrent Admission Replan' 'explicit expected revision' 'Concurrency owns stale-read' '## Child 25.1 Admission Revision Representation Replan' '`planning-admission-v1`' '## Child 25.1 Revision-Checked Serial Integration Replan' 'two revision gates' '## Child 25.1 Revision Evidence Replan' '## Child 25.1 Partial Integration Recovery Replan' '`complete-transition`' '`restore-prior-state`' '`supersede-transition`' 'Recovery never reuses' 'state-file-wins or' 'ledger-wins' 'No recovery journal' '## Re-plan Triggers';do rg -F -q "$t" "$S/milestone-7-row-25-decomposition.md";done
for t in 'Independent transitions may be planned or implemented concurrently' 'shared authority remain serial integration-owner writes' '## Child 25.1 Transition Envelope Replan' '`planning-transition-v1`' 'proposing actor' 'bounded write set' 'prerequisite transition identities' 'semantic outcomes' 'separate deterministic identity' 'reservations, leases, queues, heartbeats';do rg -F -q "$t" "$S/milestone-7-row-25-decomposition.md";done
rg -F -q '`7.4b15a` (`Accepted`)' "$P";rg -F -q '`7.4b15b` (`Accepted`)' "$P";rg -F -q '`7.4b15c` (`Accepted`)' "$P";rg -F -q '`7.4b15d` (`Accepted`)' "$P"
next="$(awk '/^\*\*Next slice:\*\*/{c=1}c&&/^$/{exit}c{print}' "$P")";[[ "$next" == *'Milestone 7.4b16a'* && "$next" == *'row 26'* && "$next" == *'STD-0859'* && "$next" == *'STD-0887'* ]]
"$S/verify-milestone-7-execution-train.sh"
"$S/verify-planning-admission.sh"
"$S/verify-plan-implementation-entrypoint.sh"
printf 'Milestone 7 row-25 decomposition passed: 7 snapshot IDs assigned to one Implementation-owned child\n'
